const $=s=>document.querySelector(s);const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state=null,currentView='overview',selectedMeeting=null,meetingFilter='全部状态',query='',currentPerson='';
const palette=['lavender','peach','mint','blue'];const localDate=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
function initialOf(s){return (s||'?').slice(0,1)}
function avatar(name,idx=0,cls='',userId=''){const person=userId?state?.people?.find(p=>p.id===userId):null,image=(userId===currentUser?.id?currentUser?.avatar:'')||person?.avatar||'';return image?`<img class="avatar avatar-image ${cls}" src="${esc(image)}" alt="${esc(name)}头像">`:`<span class="avatar avatar-${palette[idx%palette.length]} ${cls}">${esc(initialOf(name))}</span>`}
let currentUser=null,currentProjects=[],currentProjectId=localStorage.getItem('projectId')||'',projectQuery='',projectStatus='全部项目',logAuthorFilter='全部成员',logQuery='',eventTypeFilter='全部动态',eventPersonFilter='全部成员',eventFrom='',eventTo='',showMine=false,workMemberFilter='全部成员',eventLimit=20;
function uniquePersonByName(name){const matches=(state?.people||[]).filter(p=>p.name===name);return matches.length===1?matches[0]:null}
function belongsToCurrent(storedId,name,user=currentUser){return !!user&&(storedId?storedId===user.id:uniquePersonByName(name)?.id===user.id)}
async function load(){setConnection('loading','正在连接');try{const me=await fetch('/api/me',{credentials:'same-origin'});if(me.status===401){setConnection('offline','未登录');renderAuth();return}if(!me.ok)throw new Error(`登录状态读取失败（${me.status}）`);currentUser=await me.json();syncUserMenu();const pr=await fetch('/api/projects',{credentials:'same-origin'});if(!pr.ok)throw new Error(`项目列表读取失败（${pr.status}）`);currentProjects=await pr.json();if(!currentProjects.length){state=null;setConnection('saved','已登录');renderProjects();return}if(!currentProjects.some(p=>p.id===currentProjectId))currentProjectId=currentProjects[0].id;localStorage.setItem('projectId',currentProjectId);const r=await fetch('/api/state',{credentials:'same-origin',headers:{'X-Project-Id':currentProjectId}});if(r.status===401){setConnection('offline','登录已过期');renderAuth();return}if(!r.ok)throw new Error(`项目数据读取失败（${r.status}）`);state=await r.json();currentUser.role=state.people.find(p=>p.id===currentUser.id)?.role||'成员';setConnection('saved','服务端已保存');render()}catch(e){setConnection('offline','连接失败');const target=$('#page-content');if(target)target.innerHTML=`<section class="load-error"><div class="error-symbol">!</div><h2>暂时无法读取项目数据</h2><p>${esc(e.message)}。请检查服务是否运行后重试。</p><button class="button primary" data-action="retry-load">重新加载</button></section>`}}
function setConnection(status,label){const el=$('#connection-status');if(el){el.dataset.status=status;el.innerHTML=`<i></i>${label}`}}
function renderAuth(mode='login'){let layer=document.querySelector('.auth-layer');if(!layer){document.body.insertAdjacentHTML('beforeend','<div class="auth-layer" id="auth-layer"></div>');layer=$('#auth-layer')}layer.innerHTML=`<section class="auth-card"><div class="auth-brand"><span class="brand-mark" aria-hidden="true"><svg viewBox="0 0 40 40" fill="none"><path d="M12 11.5h12a4 4 0 0 1 4 4v5a4 4 0 0 1-4 4h-5l-6 4v-4h-1a4 4 0 0 1-4-4v-5a4 4 0 0 1 4-4Z" stroke="#fff" stroke-width="2.6" stroke-linejoin="round"/><path d="M19 18h9a4 4 0 0 1 4 4v5a4 4 0 0 1-4 4h-4l-4 3v-7" stroke="#fff" stroke-width="2.6" stroke-linejoin="round"/></svg></span><div><b>协同</b><small>PROJECT COLLABORATION</small></div></div><div class="eyebrow">同频会议与协作系统</div><h1>${mode==='login'?'欢迎回来':'创建账号'}</h1><p>${mode==='login'?'登录后继续你的项目协作。':'创建账号后登录，可新建项目或确认加入邀请。'}</p><form id="auth-form"><input type="hidden" name="mode" value="${mode}">${mode==='register'?'<label>显示姓名<input name="name" required maxlength="20" placeholder="你的姓名"></label>':''}<label>账号<input name="account" required autocomplete="username" placeholder="4–30位字母、数字或下划线"></label><label>密码<input name="password" type="password" required minlength="6" maxlength="32" autocomplete="${mode==='login'?'current-password':'new-password'}" placeholder="至少6位"></label>${mode==='register'?'<label>确认密码<input name="confirmPassword" type="password" required minlength="6" maxlength="32" autocomplete="new-password" placeholder="再次输入密码"></label>':''}<button class="button primary auth-submit" type="submit">${mode==='login'?'登录项目空间':'创建账号'}</button></form><button class="auth-toggle" data-auth-mode="${mode==='login'?'register':'login'}">${mode==='login'?'没有账号？立即注册':'已有账号？返回登录'}</button>${mode==='login'?'<div class="demo-access"><b>演示账号（演示数据）</b><span>组长 lin　密码 demo1234</span><span>成员 zhou / chen / xu　密码 demo1234</span></div>':''}</section>`;layer.hidden=false}
function renderSide(){if(!state)return;$('#side-people').innerHTML=state.people.map((p,i)=>`<button class="person-chip person-chip-button" data-action="member-timeline" data-person="${esc(p.id)}" title="查看${esc(p.name)}的个人时间线">${avatar(p.name,i,'',p.id)}<span>${esc(p.name)}</span><span class="person-role">${esc(p.role)}</span><span class="person-open" aria-hidden="true">↗</span></button>`).join('');$('#meeting-count').textContent=state.meetings.length;document.querySelectorAll('.nav-item[data-view]').forEach(x=>x.classList.toggle('active',x.dataset.view===currentView));const profile=$('.profile');if(profile&&currentUser)profile.innerHTML=`${avatar(currentUser.name,0,'',currentUser.id)}<button class="profile-account-link" data-view="profile"><b>${esc(currentUser.name)}</b><span>${esc(state.people.find(p=>p.id===currentUser.id)?.role||'项目成员')} · 个人账户</span></button><button class="more-button" data-action="logout">退出</button>`;const crumb=$('.breadcrumbs strong');if(crumb)crumb.textContent=state.project.name;const name=$('#active-project-name');if(name)name.textContent=state.project.name;const initial=$('#workspace-initial');if(initial)initial.textContent=initialOf(state.project.name);const label=$('#active-project-label');if(label)label.textContent=state.project.demo?'演示数据':state.project.status==='已归档'?'只读归档项目':'我的项目空间';const menu=$('#project-menu');if(menu)menu.innerHTML=currentProjects.map(p=>`<button class="project-menu-item ${p.id===currentProjectId?'selected':''}" data-action="open-project" data-project="${esc(p.id)}"><span class="project-menu-mark">${esc(initialOf(p.name))}</span><span class="project-menu-copy"><b>${esc(p.name)}</b><small>${esc(p.status)}${p.demo?' · 演示数据':''}</small></span><span class="project-menu-check">${p.id===currentProjectId?'✓':''}</span></button>`).join('');const invite=$('#invite-mini');if(invite)invite.hidden=currentUser.role!=='组长'||state.project.status==='已归档';syncUserMenu();const progress=$('.project-progress');if(progress)progress.innerHTML=`<div class="progress-copy"><span>当前概况</span><b>${esc(state.project.status)}</b></div><div class="sidebar-facts"><span>进行中会议 <b>${state.meetings.filter(m=>m.status==='进行中').length}</b></span><span>分配给我 <b>${state.assignments.filter(a=>belongsToCurrent(a.ownerId,a.owner)).length}</b></span></div>`}
function renderProjects(){currentView='projects';document.querySelectorAll('.nav-item[data-view]').forEach(x=>x.classList.toggle('active',x.dataset.view==='projects'));const shown=currentProjects.filter(p=>(projectStatus==='全部项目'||p.status===projectStatus)&&(!projectQuery||p.name.toLowerCase().includes(projectQuery.toLowerCase())));const cards=shown.map((p,i)=>`<article class="project-card ${p.id===currentProjectId?'current-project':''}"><div class="project-card-top"><span class="project-mark">${esc(initialOf(p.name))}</span>${p.demo?'<span class="demo-tag">演示项目</span>':''}<span class="status-pill ${p.status==='已归档'?'archived':''}">${esc(p.status)}</span></div><h2>${esc(p.name)}</h2><p>${esc(p.topic||'暂无项目说明')}</p><div class="project-card-meta"><span>我的角色</span><b>${esc(p.role)}</b><span class="project-period">${esc(p.startDate||'')}</span></div><button class="button ${i===0?'primary':''}" data-action="open-project" data-project="${esc(p.id)}">${p.status==='已归档'?'查看归档':'打开项目'} <span>→</span></button></article>`).join('');const activeCount=currentProjects.filter(p=>p.status==='进行中').length,archivedCount=currentProjects.filter(p=>p.status==='已归档').length;$('#page-content').innerHTML=`${heading('PROJECT SPACES','我的项目','项目、会议与协作记录都按项目空间隔离。',button('＋ 创建项目','create-project',true)+button('使用邀请码加入','accept-invite'))}<div class="filters"><input class="search-input" id="project-search" placeholder="搜索项目名称…" value="${esc(projectQuery)}"><select class="filter-select" id="project-filter">${['全部项目','进行中','已归档'].map(x=>`<option ${projectStatus===x?'selected':''}>${x}</option>`).join('')}</select><span class="subtle">${shown.length} 个项目</span></div><div class="projects-layout"><div class="projects-grid">${cards||`<div class="empty-state">${currentProjects.length?'没有符合筛选条件的项目。':'这里还没有项目。创建项目，或使用邀请码加入协作空间。'}</div>`}</div><aside class="project-aside"><div class="eyebrow">项目概况</div><h3>项目概况</h3><p>已加入的项目和历史归档集中在这里。项目内容仅对项目成员开放。</p><div class="project-aside-stats"><div><b>${activeCount}</b><span>进行中</span></div><div><b>${archivedCount}</b><span>已归档</span></div></div><button class="button" data-action="create-project">＋ 创建新项目</button><button class="button" data-action="accept-invite">输入邀请码</button></aside></div>`}

function heading(eyebrow,title,description,actions=''){const labels={'PERSONAL ACCOUNT':'个人账户','FIELD NOTES':'工作记录','MEETING DETAIL':'会议详情','MEETING ROOM':'会议安排','MEMBER ACTIVITY':'成员时间线','PROJECT MEMBERS':'项目成员','PROJECT RECORD':'项目动态','PROJECT SETTINGS':'项目管理','PROJECT SPACES':'项目空间','PROJECT WORKSPACE':'项目协作','WORK ASSIGNMENTS':'责任分工'};return `<div class="page-heading"><div><div class="eyebrow">${labels[eyebrow]||eyebrow}</div><h1>${title}</h1><p>${description}</p></div><div class="heading-actions">${actions}</div></div>`}
function button(label,act,primary=false,extra=''){return `<button class="button ${primary?'primary':''} ${extra}" data-action="${act}">${label}</button>`}
function pill(status){const cl=status==='已结束'?'done':'';return `<span class="meeting-status ${cl}">${esc(status)}</span>`}
function dateBox(date){const d=new Date(date+'T00:00:00');return `<div class="date-box"><b>${d.getDate()}</b><span>${d.getMonth()+1}月</span></div>`}
function personLabel(p){return `${p.name} · ${p.account||p.id.slice(0,6)}`}
function meetingMembers(m){return Array.isArray(m.attendeeIds)?m.attendeeIds.map(id=>state.people.find(p=>p.id===id)).filter(Boolean):(m.attendees||[]).map(uniquePersonByName).filter(Boolean)}
function hasChecked(m,p){return Array.isArray(m.checkedIds)?m.checkedIds.includes(p.id):(m.checked||[]).includes(p.name)&&uniquePersonByName(p.name)?.id===p.id}
function meetingRow(m){return `<div class="meeting-row" data-open-meeting="${esc(m.id)}">${dateBox(m.date)}<div class="meeting-copy"><b>${esc(m.title)}</b><span>${esc(m.start)} — ${esc(m.end)} · ${esc(m.host)} 主持 · ${esc(m.format)}</span></div><div class="meeting-end">${pill(m.status)}<small>${meetingMembers(m).some(p=>p.id===currentUser?.id)?'我将参加':'项目会议'}</small></div></div>`}
function miniAssignment(a){return `<div class="assignment-item" data-open-assignment="${esc(a.id)}"><span class="assignment-mark" aria-hidden="true">·</span><div><b>${esc(a.content)}</b><span>${esc(a.owner)} · 截止 ${esc(a.due||'未设置')}</span></div></div>`}
function activityIcon(k){const paths={'会议':'<rect x="4" y="5" width="16" height="15" rx="2"/><path d="M8 3.5v3M16 3.5v3M4 9h16M8 13h3M8 16h7"/>','纪要':'<path d="M6 3.5h9l4 4v13H6a2 2 0 0 1-2-2v-13a2 2 0 0 1 2-2Z"/><path d="M14.5 3.5v5h5M8 13h8M8 16.5h6"/>','资料':'<path d="M6 3.5h9l4 4v13H6a2 2 0 0 1-2-2v-13a2 2 0 0 1 2-2Z"/><path d="M14.5 3.5v5h5M8 13h8M8 16.5h8"/>','工作日志':'<path d="M5 19 7 14 16 5a2.1 2.1 0 0 1 3 3l-9 9-5 2Z"/><path d="m14.5 6.5 3 3"/>','工作分配':'<path d="M9 6h11M9 12h11M9 18h11"/><rect x="3.5" y="4.5" width="2.5" height="2.5" rx=".5"/><rect x="3.5" y="10.5" width="2.5" height="2.5" rx=".5"/><rect x="3.5" y="16.5" width="2.5" height="2.5" rx=".5"/>','成员':'<circle cx="9" cy="8" r="3.5"/><path d="M3.5 20a5.5 5.5 0 0 1 11 0M16.5 6a3 3 0 0 1 0 5.5"/>','项目':'<rect x="3.5" y="4" width="17" height="16" rx="2"/><path d="M8 8h8M8 12h8M8 16h4"/>'};return `<svg viewBox="0 0 24 24" aria-hidden="true">${paths[k]||'<circle cx="12" cy="12" r="3"/>'}</svg>`}
function activityItem(e){return `<div class="activity-item" ${e.logId?`data-open-log="${esc(e.logId)}"`:e.assignmentId?`data-open-assignment="${esc(e.assignmentId)}"`:e.meetingId?`data-open-meeting="${esc(e.meetingId)}"`:``}><span class="activity-marker">${activityIcon(e.kind)}</span><div><b>${esc(e.title)}</b><span>${esc(e.detail)} · ${esc(e.date)}</span></div></div>`}
function overview(){const today=localDate(),base=new Date(`${today}T12:00:00+08:00`),offset=(base.getDay()+6)%7,monday=new Date(base);monday.setDate(base.getDate()-offset);const sunday=new Date(monday);sunday.setDate(monday.getDate()+6);const dateKey=d=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'}).format(d),weekStart=dateKey(monday),weekEnd=dateKey(sunday),weekItems=[...state.meetings.filter(m=>m.date>=weekStart&&m.date<=weekEnd&&m.status!=='已取消').map(m=>({id:m.id,date:m.date,time:m.start||'00:00',title:m.title,detail:`${m.host} 主持 · ${m.status}`,kind:'meeting'})),...state.assignments.filter(a=>a.due&&a.due>=weekStart&&a.due<=weekEnd).map(a=>({id:a.id,date:a.due,time:'23:59',title:a.content,detail:`${a.owner} · 计划完成日期`,kind:'assignment'}))].sort((a,b)=>a.date.localeCompare(b.date)||a.time.localeCompare(b.time));const next=state.meetings.filter(m=>m.status==='待召开'&&m.date>=today).sort((a,b)=>a.date.localeCompare(b.date)||a.start.localeCompare(b.start))[0],myUpcoming=state.meetings.filter(m=>m.status==='待召开'&&m.date>=today&&meetingMembers(m).some(p=>p.id===currentUser?.id)).length,myAssignments=state.assignments.filter(a=>belongsToCurrent(a.ownerId,a.owner)),recentEvents=state.events.slice(0,4),needsMinutes=state.meetings.filter(m=>m.status==='已结束'&&!m.summary?.trim()).sort((a,b)=>b.date.localeCompare(a.date)).slice(0,3),weekLogs=state.logs.filter(l=>l.date>=weekStart&&l.date<=weekEnd).length;return `${heading('PROJECT WORKSPACE',`早上好，${esc(currentUser?.name||'伙伴')}`,'本周安排、待跟进记录和团队动态。',state.project.status==='已归档'?'':button('＋ 发起会议','new-meeting',true)+button('写工作日志','new-log'))}<section class="hero-card overview-hero"><div class="hero-copy"><div class="hero-topline"><span class="status-pill">${esc(state.project.status)}</span><span>${state.project.demo?'<b class="demo-tag">演示项目</b>':`项目周期 ${esc(state.project.startDate)} — ${esc(state.project.endDate||'未设结束日期')}`}</span></div><h2>${esc(state.project.name)}</h2><p>${esc(state.project.topic)}</p><div class="hero-meta"><div class="meta-stat"><span>项目成员</span><b>${state.people.length} 位</b></div><div class="meta-stat"><span>我的角色</span><b>${esc(currentUser.role||'成员')}</b></div><div class="meta-stat"><span>本周工作日志</span><b>${weekLogs} 条</b></div></div></div><button class="hero-side ${next?'has-next':''}" ${next?`data-open-meeting="${esc(next.id)}"`:'data-view="meetings"'}><span>下一场会议</span><b>${next?esc(next.title):'还没有安排会议'}</b><small>${next?`${next.date} · ${next.start} · ${esc(next.host)} 主持`:'查看会议并安排下一次协作 →'}</small><i>${next?'查看会议 ↗':'＋'}</i></button></section><section class="stats-grid overview-stats"><article class="stat-card"><span>项目会议</span><span class="stat-icon">▦</span><b>${state.meetings.length}<small>场</small></b><small class="stat-note">含已取消会议</small></article><article class="stat-card"><span>我的待参会</span><span class="stat-icon">◷</span><b>${myUpcoming}<small>场</small></b><small class="stat-note">待召开且我在名单中</small></article><article class="stat-card"><span>分配给我</span><span class="stat-icon">☷</span><b>${myAssignments.length}<small>项</small></b><small class="stat-note">查看负责人和计划日期</small></article><article class="stat-card"><span>已发布日志</span><span class="stat-icon">▤</span><b>${state.logs.length}<small>条</small></b><small class="stat-note">当前项目过程记录</small></article><article class="stat-card"><span>项目成员</span><span class="stat-icon">♧</span><b>${state.people.length}<small>位</small></b><small class="stat-note">当前项目团队</small></article></section><section class="overview-grid"><div class="overview-primary"><section class="panel week-panel"><div class="panel-header"><div><div class="panel-title">本周协作节奏</div><small class="section-caption">${weekStart} — ${weekEnd} · 会议安排与分工计划日期</small></div><button class="text-link" data-view="timeline">查看时间线 →</button></div><div class="week-list">${weekItems.slice(0,7).map(item=>`<button class="week-entry" ${item.kind==='meeting'?`data-open-meeting="${esc(item.id)}"`:`data-open-assignment="${esc(item.id)}"`}><span class="week-date"><b>${esc(item.date.slice(8))}</b><small>${esc(item.date.slice(5,7))}月</small></span><span class="week-copy"><b>${esc(item.title)}</b><small>${esc(item.detail)}</small></span><span class="week-kind ${item.kind}">${item.kind==='meeting'?'会议':'分工'}</span><span class="week-time">${esc(item.kind==='meeting'?item.time:'计划日')}</span></button>`).join('')||'<div class="empty-state compact">本周暂无会议安排或分工计划日期。可发起会议，或为已有会议记录工作分配。</div>'}</div><div class="week-footer"><span>本周日志 <b>${weekLogs}</b></span><button class="text-link" data-view="journal">查看工作日志 →</button></div></section><section class="panel activity-panel"><div class="panel-header"><div><div class="panel-title">最近项目动态</div><small class="section-caption">只显示当前项目已记录的操作</small></div><button class="text-link" data-view="timeline">全部动态 →</button></div><div class="activity-list">${recentEvents.map(activityItem).join('')||'<div class="empty-state compact">项目操作会显示在这里。</div>'}</div></section></div><aside class="overview-secondary"><section class="panel focus-panel"><div class="panel-header"><div><div class="panel-title">分配给我的</div><small class="section-caption">责任事项与计划日期</small></div><button class="text-link" data-view="work">全部 →</button></div><div class="assignment-list">${myAssignments.slice().sort((a,b)=>(a.due||'9999').localeCompare(b.due||'9999')).slice(0,4).map(miniAssignment).join('')||'<div class="empty-state compact">当前没有分配给你的事项。</div>'}</div></section><section class="panel focus-panel"><div class="panel-header"><div><div class="panel-title">纪要待整理</div><small class="section-caption">已结束但尚未保存纪要</small></div><button class="text-link" data-view="meetings">查看会议 →</button></div><div class="assignment-list minutes-list">${needsMinutes.map(m=>`<button class="assignment-item" data-open-meeting="${esc(m.id)}"><span class="activity-marker">记</span><span><b>${esc(m.title)}</b><small>${esc(m.date)} · 查看会议并补充纪要</small></span><span class="focus-arrow">↗</span></button>`).join('')||'<div class="empty-state compact">已结束会议均有纪要记录。</div>'}</div></section><section class="panel focus-panel focus-shortcuts"><div class="panel-header"><div><div class="panel-title">常用入口</div><small class="section-caption">快速继续项目协作</small></div></div><div class="shortcut-grid"><button data-view="meetings"><span>▦</span>会议安排</button><button data-view="members"><span>♧</span>成员与邀请</button><button data-view="personal"><span>◷</span>个人时间线</button><button data-view="settings"><span>⚙</span>项目设置</button></div>${currentUser.role==='组长'&&state.project.status!=='已归档'?`<div class="lead-workbench"><div><b>组长工作台</b><small>成员与项目日程管理</small></div><div class="lead-workbench-stats"><span>项目成员 <b>${state.people.length}</b></span><span>待召开 <b>${state.meetings.filter(m=>m.status==='待召开').length}</b></span><span>有效邀请 <b>${(state.invites||[]).filter(i=>i.status==='有效').length}</b></span></div><div class="lead-workbench-actions"><button class="button small" data-action="invite-mini">邀请成员</button><button class="button small" data-view="members">查看成员</button></div></div>`:''}</section></aside></section>`}
function meetings(){const today=localDate(),live=state.meetings.filter(m=>m.status==='进行中').sort((a,b)=>a.date.localeCompare(b.date)||a.start.localeCompare(b.start))[0],next=state.meetings.filter(m=>m.status==='待召开'&&m.date>=today).sort((a,b)=>a.date.localeCompare(b.date)||a.start.localeCompare(b.start))[0],featured=live||next,active=state.meetings.filter(m=>m.status==='进行中').length,upcoming=state.meetings.filter(m=>m.status==='待召开'&&m.date>=today).length,ended=state.meetings.filter(m=>m.status==='已结束').length,materials=(state.files||[]).filter(f=>f.meetingId).length;const list=state.meetings.filter(m=>(meetingFilter==='全部状态'||m.status===meetingFilter)&&(!query||`${m.title} ${m.topic} ${m.host} ${m.organizer}`.toLowerCase().includes(query.toLowerCase()))).sort((a,b)=>{const rank=m=>m.status==='进行中'?0:m.status==='待召开'&&m.date>=today?1:m.status==='已取消'?3:2,r=rank(a)-rank(b);if(r)return r;if(a.status==='待召开'&&b.status==='待召开')return a.date.localeCompare(b.date)||a.start.localeCompare(b.start);return b.date.localeCompare(a.date)||b.start.localeCompare(a.start)});return `${heading('MEETING ROOM','会议安排','从日程、参会名单到会议资料与纪要，在一处跟进。',state.project.status==='已归档'?'':button('＋ 发起会议','new-meeting',true))}<section class="meeting-next ${featured?'':'empty'}"><div class="meeting-next-copy"><span class="eyebrow">${featured?.status==='进行中'?'正在进行':featured?'下一场会议':'项目日程'}</span><h2>${featured?esc(featured.title):'先把下一次讨论排进日程'}</h2><p>${featured?`${esc(featured.date)} · ${esc(featured.start)}–${esc(featured.end)} · ${esc(featured.host)} 主持 · ${meetingMembers(featured).length} 位应参会成员`:'会议安排、参会名单、签到和纪要会集中显示在这里。'}</p></div>${featured?`<button class="button primary" data-open-meeting="${esc(featured.id)}">${featured.status==='进行中'?'进入会议记录':'查看会议安排'} →</button>`:state.project.status!=='已归档'?button('创建第一场会议','new-meeting',true):''}</section><section class="meeting-summary-grid"><article><span>进行中</span><b>${active}</b><small>正在协作</small></article><article><span>待召开</span><b>${upcoming}</b><small>未来日程</small></article><article><span>已结束</span><b>${ended}</b><small>可查纪要与资料</small></article><article><span>会议资料</span><b>${materials}</b><small>项目内可访问</small></article></section><div class="filters meeting-filters"><select class="filter-select" id="meeting-filter"><option>全部状态</option>${['待召开','进行中','已结束','已取消'].map(s=>`<option ${meetingFilter===s?'selected':''}>${s}</option>`).join('')}</select><input class="search-input" id="meeting-search" placeholder="搜索会议、议题或主持人…" value="${esc(query)}"><span class="subtle" style="font-size:10px;margin-left:auto">显示 ${list.length} / ${state.meetings.length} 场</span></div><div class="meeting-table-panel table-panel"><div class="table-head meeting-table-head"><span>会议与议题</span><span>时间</span><span>主持 / 发起</span><span>参会名单</span><span>状态</span></div>${list.length?list.map(m=>`<button class="table-row meeting-table-row" data-open-meeting="${esc(m.id)}"><span class="meeting-name-cell"><span class="meeting-mini-icon">${activityIcon('会议')}</span><span><b class="table-title">${esc(m.title)}</b><small class="table-sub">${esc(m.topic)}</small></span></span><span>${esc(m.date)}<small class="table-sub">${esc(m.start)} — ${esc(m.end)}</small></span><span>${esc(m.host)}<small class="table-sub">发起人 ${esc(m.organizer)}</small></span><span>${meetingMembers(m).map(person=>`<span class="meeting-attendee-chip">${esc(initialOf(person.name))}</span>`).join('')}<small class="table-sub">${meetingMembers(m).length} 位成员</small></span><span>${pill(m.status)}</span></button>`).join(''):'<div class="empty-state">没有符合条件的会议。换一个筛选条件，或创建一场新会议。</div>'}</div>`}
function work(){const visible=state.assignments.filter(a=>(!showMine||belongsToCurrent(a.ownerId,a.owner))&&(workMemberFilter==='全部成员'||a.ownerId===workMemberFilter||(!a.ownerId&&uniquePersonByName(a.owner)?.id===workMemberFilter)));const canCreate=currentUser.role==='组长'||state.meetings.some(m=>belongsToCurrent(m.organizerId,m.organizer)||belongsToCurrent(m.hostId,m.host));const selected=state.people.find(p=>p.id===workMemberFilter);return `${heading('WORK ASSIGNMENTS','工作分配','责任事项记录内容、负责人、关联会议和计划日期，不含验收状态。',`${canCreate&&state.project.status!=='已归档'?button('＋ 新增分工','new-assignment',true):''}<button class="button ${showMine?'primary':''}" data-action="toggle-mine">${showMine?'查看全部':'分配给我'}</button><button class="button" data-view="journal">查看工作日志</button>`)}<div class="work-summary"><div><span>当前视图</span><b>${showMine?'分配给我':selected?`${esc(selected.name)} 的分工`:'全部分工'}</b><small>${visible.length} 项责任事项 · 按会议关联留档</small></div><button class="button ${workMemberFilter==='全部成员'&&!showMine?'primary':''}" data-action="filter-assignment-owner" data-owner="全部成员">全部成员</button></div><div class="work-grid"><div class="work-card-list">${visible.map(a=>`<article class="work-card" data-assignment="${esc(a.id)}"><div class="work-top"><span class="assignment-mark" aria-hidden="true">·</span><div class="work-main"><b>${esc(a.content)}</b><p>关联会议 · ${esc(a.meeting)}</p>${a.note?`<small class="work-note">${esc(a.note)}</small>`:''}</div></div><div class="work-meta"><span>负责人　${esc(a.owner)}</span><span>分配人　${esc(a.by)}</span><span class="due-badge">计划完成　${esc(a.due||'未设置')}</span></div><div class="work-card-actions"><button class="text-link" data-action="view-assignment" data-id="${esc(a.id)}">查看详情 →</button>${(currentUser.role==='组长'||state.meetings.some(m=>(m.id===a.meetingId||m.title===a.meeting)&&(belongsToCurrent(m.organizerId,m.organizer)||belongsToCurrent(m.hostId,m.host))))&&state.project.status!=='已归档'?`<button class="text-link" data-action="edit-assignment" data-id="${esc(a.id)}">调整分配</button>`:''}</div>${(a.changeHistory||[]).slice(0,3).map(h=>`<small class="history-line">${esc(String(h.at||'').slice(0,16).replace('T',' '))} · ${esc(h.by)} 调整了负责人/安排</small>`).join('')}</article>`).join('')||`<div class="empty-state">${showMine?'目前没有分配给你的事项。':'该成员目前没有分工记录。'}<br>新增分工时可指定负责人，并关联会议。</div>`}</div><aside class="panel member-work-panel"><div class="panel-header"><div><div class="panel-title">按负责人筛选</div><small class="subtle">点击成员查看其分工</small></div><span class="subtle" style="font-size:9px">${state.people.length} 人</span></div><div class="member-work-list">${state.people.map((p,i)=>{const count=state.assignments.filter(a=>a.ownerId===p.id||(!a.ownerId&&uniquePersonByName(a.owner)?.id===p.id)).length;return `<button class="member-work-row ${workMemberFilter===p.id?'selected':''}" data-action="filter-assignment-owner" data-owner="${esc(p.id)}" aria-pressed="${workMemberFilter===p.id}">${avatar(p.name,i,'',p.id)}<b>${esc(p.name)}</b><span>${count} 项</span><i>›</i></button>`}).join('')}</div></aside></div>`}
function logCard(l){const i=state.people.findIndex(p=>p.id===l.authorId||(!l.authorId&&uniquePersonByName(l.author)?.id===p.id)),own=belongsToCurrent(l.authorId,l.author),meeting=state.meetings.find(m=>m.id===l.meetingId);return `<article class="log-card" data-log="${esc(l.id)}"><div class="log-header">${avatar(l.author,i<0?0:i,'',l.authorId||'')}<b>${esc(l.author)}</b><span>工作日期 ${esc(l.date)}</span><span class="log-date">${esc(l.time||'')}</span>${own?`<button class="text-link" data-action="edit-log" data-id="${esc(l.id)}">编辑</button>`:''}<a class="text-link" href="/api/export?kind=log&id=${encodeURIComponent(l.id)}&format=docx">导出 Word</a><a class="text-link" href="/api/export?kind=log&id=${encodeURIComponent(l.id)}&format=pdf">PDF</a></div><div class="log-text rich-readonly">${richContent(l.textHtml,l.text)}</div><div class="log-relations">${meeting?`<button class="log-link" data-open-meeting="${esc(meeting.id)}">会议 · ${esc(meeting.title)}　↗</button>`:''}${l.link?l.linkAssignmentId?`<button class="log-link" data-open-assignment="${esc(l.linkAssignmentId)}">分工 · ${esc(l.link)}　↗</button>`:`<span class="log-link">关联分工 · ${esc(l.link)}</span>`:''}</div>${(state.files||[]).filter(f=>f.logId===l.id).map(f=>`<div class="attendee-row">▧　${esc(f.name)} <a class="text-link" href="/api/files/download?id=${encodeURIComponent(f.id)}&projectId=${encodeURIComponent(currentProjectId)}">下载</a><span class="attendee-state">${esc(f.uploadedBy)} · ${esc((f.uploadedAt||'').slice(0,10))}</span></div>`).join('')}</article>`}
function journal(){const rows=state.logs.filter(l=>(logAuthorFilter==='全部成员'||l.authorId===logAuthorFilter||(!l.authorId&&l.author===logAuthorFilter))&&(!logQuery||l.text.toLowerCase().includes(logQuery.toLowerCase()))).sort((a,b)=>b.date.localeCompare(a.date)||String(b.time).localeCompare(String(a.time))),today=localDate(),weekAgo=new Date(`${today}T12:00:00+08:00`);weekAgo.setDate(weekAgo.getDate()-6);const weekKey=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'}).format(weekAgo),weekCount=state.logs.filter(l=>l.date>=weekKey&&l.date<=today).length,myCount=state.logs.filter(l=>belongsToCurrent(l.authorId,l.author)).length;return `${heading('FIELD NOTES','工作日志','按日期沉淀实际进展；打开关联会议或分工，可继续查看上下文。',state.project.status==='已归档'?'':button('＋ 写工作日志','new-log',true))}<section class="journal-summary"><div><span>项目记录</span><b>${state.logs.length}</b><small>条已发布日志</small></div><div><span>近 7 天</span><b>${weekCount}</b><small>条工作记录</small></div><div><span>我的日志</span><b>${myCount}</b><small>当前项目内</small></div><p>日志保留作者和日期。只有作者本人可以修改，导出只包含服务端已保存版本。</p></section><div class="filters journal-filters"><select class="filter-select" id="log-author-filter"><option>全部成员</option>${state.people.map(p=>`<option value="${esc(p.id)}" ${logAuthorFilter===p.id?'selected':''}>${esc(personLabel(p))}</option>`).join('')}</select><input class="search-input" id="log-search" placeholder="搜索日志正文…" value="${esc(logQuery)}"><span class="subtle" style="font-size:10px;margin-left:auto">当前显示 ${rows.length} / ${state.logs.length} 条</span></div><div class="timeline-wrap journal-list">${rows.map(logCard).join('')||'<div class="empty-state">没有符合条件的日志。调整筛选，或新增一条工作日志。</div>'}</div>`}

function timeline(){const sorted=[...state.events].filter(e=>(eventTypeFilter==='全部动态'||e.kind===eventTypeFilter)&&(eventPersonFilter==='全部成员'||e.actorId===eventPersonFilter||e.personId===eventPersonFilter||e.affectedMemberIds?.includes(eventPersonFilter))&&(!eventFrom||e.date>=eventFrom)&&(!eventTo||e.date<=eventTo)).sort((a,b)=>String(b.at||b.date).localeCompare(String(a.at||a.date))),visible=sorted.slice(0,eventLimit),activeMeetings=state.meetings.filter(m=>m.status==='进行中').length;let last='';return `${heading('PROJECT RECORD','项目时间线','查看会议、签到、资料、分工和日志留下的协作记录；选择成员或来源回到原始内容。','')}<section class="timeline-summary"><div><span>事件记录</span><b>${state.events.length}</b><small>当前项目</small></div><div><span>当前筛选</span><b>${sorted.length}</b><small>条结果</small></div><div><span>进行中会议</span><b>${activeMeetings}</b><small>查看参会与签到</small></div><button class="button" data-view="personal">查看个人时间线 →</button></section><div class="filters timeline-filters"><select class="filter-select" id="event-filter"><option>全部动态</option>${['会议','纪要','资料','工作分配','工作日志','成员','项目'].map(k=>`<option ${eventTypeFilter===k?'selected':''}>${k}</option>`).join('')}</select><select class="filter-select" id="event-person-filter"><option>全部成员</option>${state.people.map(p=>`<option value="${esc(p.id)}" ${eventPersonFilter===p.id?'selected':''}>${esc(personLabel(p))}</option>`).join('')}</select><input class="filter-select" id="event-from" type="date" aria-label="开始日期" value="${esc(eventFrom)}"><input class="filter-select" id="event-to" type="date" aria-label="结束日期" value="${esc(eventTo)}"><span class="subtle">${eventFrom||'不限开始'} 至 ${eventTo||'不限结束'}</span></div><div class="timeline-wrap timeline-list" id="timeline-list">${visible.map(e=>{const day=e.date,header=day!==last?(last=day,`<div class="timeline-day"><b>${esc(day)}</b><span>${esc(new Date(`${day}T12:00:00`).toLocaleDateString('zh-CN',{weekday:'long'}))}</span></div>`):'',source=e.logId?`data-open-log="${esc(e.logId)}"`:e.assignmentId?`data-open-assignment="${esc(e.assignmentId)}"`:e.meetingId?`data-open-meeting="${esc(e.meetingId)}"`:'';return `${header}<article class="timeline-item timeline-item-rich" data-event-kind="${esc(e.kind)}" ${source}><span class="timeline-dot">${activityIcon(e.kind)}</span><div class="timeline-content"><div class="timeline-item-heading"><b>${esc(e.title)}</b><span class="event-kind-tag">${esc(e.kind)}</span></div><p>${esc(e.detail)}</p><small>${esc(e.at?String(e.at).slice(11,16):'')} ${esc(e.date)} · ${source?'打开关联记录 →':'项目记录'}</small></div><span class="timeline-arrow">↗</span></article>`}).join('')||'<div class="empty-state">当前筛选范围内没有项目事件。修改筛选，或前往会议、分工与日志继续协作。</div>'}</div>${sorted.length>eventLimit?`<button class="button" data-action="timeline-more">继续加载（已显示 ${eventLimit} 条，共 ${sorted.length} 条）</button>`:''}`}

function members(){return `${heading('PROJECT MEMBERS','项目成员','查看项目成员、加入时间，进入成员在本项目内的个人时间线。',currentUser.role==='组长'&&state.project.status!=='已归档'?button('＋ 邀请成员','invite-member',true):'')}<div class="table-panel"><div class="table-head" style="grid-template-columns:1.3fr 1fr 1fr 1fr"><span>成员</span><span>项目角色</span><span>加入时间</span><span>参与记录</span></div>${state.people.map((p,i)=>`<div class="table-row" style="grid-template-columns:1.3fr 1fr 1fr 1fr"><span style="display:flex;align-items:center;gap:9px">${avatar(p.name,i,'',p.id)}<span><span class="table-title">${esc(p.name)}</span><span class="table-sub">@${esc(p.account||p.id.slice(0,6))}</span></span></span><span>${esc(p.role)}</span><span class="subtle">${esc(p.joined)}</span><button class="text-link" data-action="member-timeline" data-person="${esc(p.id)}">查看个人时间线 →</button></div>`).join('')}</div><section class="panel" style="margin-top:15px"><div class="panel-header"><div class="panel-title">邀请记录</div><span class="subtle" style="font-size:9px">邀请链接有效期 7 天</span></div><div class="assignment-list">${(state.invites||[]).map(i=>`<div class="assignment-item"><span class="activity-marker">＋</span><div><b>邀请码 ${esc(i.code)}</b><span>${esc(i.status)} · 到期 ${esc(i.expiresAt.slice(0,10))}</span></div>${i.status==='有效'?`<button class="text-link" data-action="revoke-invite" data-id="${esc(i.id)}">失效</button>`:''}</div>`).join('')||'<div class="empty-state">还没有邀请记录</div>'}</div></section>`}
function personal(){const p=state.people.find(x=>x.id===currentPerson||x.name===currentPerson)||state.people.find(x=>x.id===currentUser?.id)||state.people[0],assignments=state.assignments.filter(a=>a.ownerId===p.id||(!a.ownerId&&uniquePersonByName(a.owner)?.id===p.id)),logs=state.logs.filter(l=>l.authorId===p.id||(!l.authorId&&uniquePersonByName(l.author)?.id===p.id)),meetings=state.meetings.filter(m=>belongsToCurrent(m.hostId,m.host,p)||belongsToCurrent(m.organizerId,m.organizer,p)||meetingMembers(m).some(x=>x.id===p.id)),checkins=state.meetings.flatMap(m=>(m.attendance||[]).filter(a=>a.personId===p.id).map(a=>({m,a}))),related=state.events.filter(ev=>ev.actorId===p.id||ev.personId===p.id||ev.affectedMemberIds?.includes(p.id)||meetings.some(m=>m.id===ev.meetingId)||assignments.some(a=>a.id===ev.assignmentId)||logs.some(l=>l.id===ev.logId)),entries=[...related.map(e=>({id:e.id,title:e.title,detail:e.detail,date:e.date,at:e.at||e.date,kind:e.kind,meetingId:e.meetingId,assignmentId:e.assignmentId,logId:e.logId})),...meetings.map(m=>({id:`participation:${m.id}`,title:meetingMembers(m).some(x=>x.id===p.id)?`应邀参会：${m.title}`:belongsToCurrent(m.hostId,m.host,p)?`主持会议：${m.title}`:`发起会议：${m.title}`,detail:`${m.date} · ${m.status} · ${m.start||''}–${m.end||''} · ${m.host} 主持`,date:m.date,at:m.date,kind:'会议',meetingId:m.id})),...checkins.filter(x=>!related.some(e=>e.meetingId===x.m.id&&/签到/.test(e.title))).map(({m,a})=>({id:`checkin:${m.id}:${p.id}`,title:a.method==='组长补签'?'组长补录签到':`${p.name} 完成签到`,detail:`${m.title} · ${a.method||'本人签到'}${a.reason?` · 原因：${a.reason}`:''}`,date:(a.at||m.date).slice(0,10),at:a.at||m.date,kind:'会议',meetingId:m.id})),...assignments.filter(a=>!related.some(e=>e.assignmentId===a.id)).map(a=>({id:`assignment:${a.id}`,title:`负责事项：${a.content}`,detail:`关联会议 ${a.meeting||'未记录'} · 计划完成 ${a.due||'未设置'}`,date:a.due||state.project.startDate,at:a.due||state.project.startDate,kind:'工作分配',assignmentId:a.id})),...logs.filter(l=>!related.some(e=>e.logId===l.id)).map(l=>({id:`log:${l.id}`,title:'发布了工作日志',detail:l.text,date:l.date,at:l.createdAt||l.date,kind:'工作日志',logId:l.id}))].sort((a,b)=>String(b.at).localeCompare(String(a.at))),isSelf=p.id===currentUser.id;return `${heading('MEMBER ACTIVITY',`${esc(p.name)} · ${isSelf?'我的':'成员'}时间线`,'只汇总此成员在当前项目中的受邀会议、签到、负责事项和本人记录。',`<label class="timeline-person-select"><span>查看成员</span><select id="personal-person-filter">${state.people.map(person=>`<option value="${esc(person.id)}" ${person.id===p.id?'selected':''}>${esc(person.name)} · ${esc(person.role)}</option>`).join('')}</select></label>`)}<section class="person-timeline-hero">${avatar(p.name,state.people.indexOf(p),'person-timeline-avatar',p.id)}<div><span>${esc(p.role)} · 加入于 ${esc(p.joined||'未记录')}</span><h2>${esc(p.name)} 的项目轨迹</h2><p>所有内容限定在「${esc(state.project.name)}」；时间线只展示项目已有记录，不计算贡献分或完成率。</p></div><button class="button" data-view="members">项目成员 →</button></section><section class="stats-grid personal-stats"><article class="stat-card"><span>相关会议</span><b>${meetings.length}<small>场</small></b><small class="stat-note">受邀、主持或发起</small></article><article class="stat-card"><span>签到记录</span><b>${checkins.length}<small>次</small></b><small class="stat-note">含组长补签留痕</small></article><article class="stat-card"><span>负责事项</span><b>${assignments.length}<small>项</small></b><small class="stat-note">仅表示责任分配</small></article><article class="stat-card"><span>工作日志</span><b>${logs.length}<small>条</small></b><small class="stat-note">本人发布</small></article></section><div class="timeline-wrap timeline-list personal-timeline-list">${entries.map(e=>`<article class="timeline-item timeline-item-rich" ${e.logId?`data-open-log="${esc(e.logId)}"`:e.assignmentId?`data-open-assignment="${esc(e.assignmentId)}"`:e.meetingId?`data-open-meeting="${esc(e.meetingId)}"`:''}><span class="timeline-dot">${activityIcon(e.kind)}</span><div class="timeline-content"><div class="timeline-item-heading"><b>${esc(e.title)}</b><span class="event-kind-tag">${esc(e.kind)}</span></div><p>${esc(e.detail)}</p><small>${esc(String(e.date||'').slice(0,10))} ${e.meetingId||e.assignmentId||e.logId?'· 打开关联记录 →':''}</small></div><span class="timeline-arrow">↗</span></article>`).join('')||'<div class="empty-state">还没有个人协作记录。参加会议、签到、负责分工或发布日志后会显示在这里。</div>'}</div>`}
function settings(){const leader=currentUser.role==='组长';return `${heading('PROJECT SETTINGS','项目设置','维护项目信息、归档状态与项目数据备份。', '')}<div class="settings-grid"><section class="settings-card"><h3>项目信息</h3><div class="field"><label>项目名称</label><input value="${esc(state.project.name)}" ${leader&&state.project.status!=='已归档'?'':'disabled'}></div><div class="field"><label>项目主题与说明</label><textarea ${leader&&state.project.status!=='已归档'?'':'disabled'}>${esc(state.project.topic)}</textarea></div><div class="form-grid"><div class="field"><label>开始日期</label><input value="${esc(state.project.startDate)}" type="date" ${leader&&state.project.status!=='已归档'?'':'disabled'}></div><div class="field"><label>计划结束日期</label><input value="${esc(state.project.endDate)}" type="date" ${leader&&state.project.status!=='已归档'?'':'disabled'}></div></div>${leader&&state.project.status!=='已归档'?'<button class="button" data-action="save-project">保存项目信息</button>':'<div class="status-banner">项目只读或你是项目成员，不能修改项目信息。</div>'}</section><section class="settings-card"><h3>项目归档</h3><p>归档后，项目中的会议、资料、纪要、分工和日志将进入只读状态。成员仍可查阅历史内容和下载资料。</p><div class="status-banner">归档前需先结束或取消所有待召开、进行中的会议。</div>${leader&&state.project.status!=='已归档'?'<button class="button danger" data-action="archive-project">归档项目</button>':''}</section><section class="settings-card backup-card"><div class="backup-heading"><span class="eyebrow">DATA PORTABILITY</span><h3>项目备份与恢复</h3></div><p>备份包含当前项目记录、成员关系和项目附件。恢复仅接受同一项目 ID、相同成员与角色的备份。</p><div class="status-banner">恢复会覆盖当前项目数据。建议先下载一份当前备份；每个附件最多 20MB，项目附件总量最多 100MB。</div><div class="backup-actions"><button class="button" data-action="download-backup" ${leader?'':'disabled title="仅项目组长可创建备份"'}>下载项目备份 ZIP</button><button class="button danger" data-action="choose-restore" ${leader&&state.project.status!=='已归档'?'':'disabled title="仅未归档项目的组长可恢复备份"'}>选择备份并恢复</button><input type="file" id="backup-file" accept=".zip,application/zip" hidden></div><small>备份文件只在本地浏览器下载，不会上传到第三方服务。</small></section></div>`}

function richContent(html,text){return html||`<p>${esc(text||'')}</p>`}
function richEditor(kind,html,text,recordId=''){return `<div class="rich-editor-wrap" data-record-id="${esc(recordId)}"><div class="rich-toolbar" role="toolbar" aria-label="正文格式"><button type="button" data-editor-command="undo" title="撤销">↶</button><button type="button" data-editor-command="redo" title="重做">↷</button><span></span><button type="button" data-editor-command="bold" title="加粗"><b>B</b></button><button type="button" data-editor-command="italic" title="斜体"><i>I</i></button><button type="button" data-editor-command="underline" title="下划线"><u>U</u></button><button type="button" data-editor-command="color" title="文字颜色">A▾</button><button type="button" data-editor-command="highlight" title="文字高亮">▰</button><span></span><button type="button" data-editor-command="h1" title="一级标题">H₁</button><button type="button" data-editor-command="h2" title="二级标题">H₂</button><button type="button" data-editor-command="h3" title="三级标题">H₃</button><button type="button" data-editor-command="insertUnorderedList" title="项目符号列表">• 列表</button><button type="button" data-editor-command="insertOrderedList" title="编号列表">1. 列表</button><button type="button" data-editor-command="checklist" title="清单">☑ 清单</button><button type="button" data-editor-command="blockquote" title="引用">❝</button><button type="button" data-editor-command="link" title="插入链接">↗</button><button type="button" data-editor-command="table" title="插入表格">▦ 表格</button><button type="button" data-editor-command="add-row" title="在当前表格添加行">＋行</button><button type="button" data-editor-command="add-column" title="在当前表格添加列">＋列</button><button type="button" data-editor-command="delete-row" title="删除当前行">−行</button><button type="button" data-editor-command="delete-column" title="删除当前列">−列</button><button type="button" data-editor-command="image" title="插入图片">▧ 图片</button><button type="button" data-editor-command="hr" title="分隔线">—</button></div><div class="rich-editor" contenteditable="true" data-rich-editor="${kind}" role="textbox" aria-multiline="true">${richContent(html,text)}</div><input type="hidden" name="${kind==='minutes'?'summary':'text'}" value="${esc(text||'')}"><input type="hidden" name="${kind==='minutes'?'summaryHtml':'textHtml'}" value="${esc(html||richContent('',text))}"><div class="editor-foot"><span data-editor-state="${kind}">已保存版本载入 · 编辑后未保存</span><span>支持标题、样式、清单、表格、链接和图片</span></div></div>`}
function meetingDetail(m){const isLeader=currentUser.role==='组长',isOrganizer=belongsToCurrent(m.organizerId,m.organizer),isHost=belongsToCurrent(m.hostId,m.host),canOperate=isLeader||isOrganizer||isHost,canWrite=state.project.status!=='已归档';const statusActions=!canWrite?'':m.status==='待召开'?(canOperate?button('开始会议','start-meeting',true):'')+((isLeader||isOrganizer)?button('取消会议','cancel-meeting',false,'danger'):''):m.status==='进行中'?(canOperate?button('结束会议','end-meeting',true):'')+((isLeader||isOrganizer)?button('取消会议','cancel-meeting',false,'danger'):''):'';return `${heading('MEETING DETAIL',esc(m.title),`${esc(m.date)} · ${esc(m.start)} — ${esc(m.end)} · ${esc(m.format)}`,`<button class="button" data-action="back-meetings">← 返回会议</button>${statusActions}`)}<div class="status-banner">${m.status==='已结束'?'会议已结束，仍可补充资料、纪要与分工。':m.status==='已取消'?'会议已取消，历史记录仍可查看。':`当前状态：${m.status}。会议记录会保留在项目空间中。`}</div><div class="meeting-detail-grid"><div><section class="detail-section"><h3>会议议题</h3><p>${esc(m.topic)}</p><div class="detail-kv"><div><span>主持人</span><b>${esc(m.host)}</b></div><div><span>会议地点 / 链接</span><b>${esc(m.location||'未填写')}</b></div><div><span>发起人</span><b>${esc(m.organizer)}</b></div><div><span>会议形式</span><b>${esc(m.format)}</b></div></div></section><section class="detail-section"><h3>会议纪要 ${canWrite&&m.status!=='已取消'&&(isLeader||isOrganizer||isHost)?'<button class="text-link" style="float:right" data-action="edit-minutes">编辑纪要</button>':''}</h3><div class="rich-readonly">${m.summary?richContent(m.summaryHtml,m.summary):'<p class="empty-copy">还没有已保存的会议纪要。</p>'}</div>${m.summary?`<div class="export-links"><a class="text-link" href="/api/export?kind=minutes&id=${encodeURIComponent(m.id)}&format=docx">导出 Word</a><a class="text-link" href="/api/export?kind=minutes&id=${encodeURIComponent(m.id)}&format=pdf">导出 PDF</a></div>`:''}</section><section class="detail-section"><h3>会议资料 ${m.status!=='已取消'&&state.project.status!=='已归档'?'<button class="text-link" style="float:right" data-action="upload-file">＋ 上传资料</button>':''}</h3><p>资料仅对当前项目成员开放。</p>${(state.files||[]).filter(f=>f.meetingId===m.id).map(f=>`<div class="attendee-row">▧　${esc(f.name)} <a class="text-link" href="/api/files/download?id=${encodeURIComponent(f.id)}&projectId=${encodeURIComponent(currentProjectId)}">下载</a><span class="attendee-state">${esc(f.uploadedBy)} · ${esc(f.uploadedAt.slice(0,10))}</span></div>`).join('')||'<p class="empty-copy">还没有会议资料，使用右上角上传按钮添加。</p>'}</section></div><div><section class="detail-section"><h3>应参会成员 <span class="subtle">${meetingMembers(m).length} 人</span></h3>${meetingMembers(m).map((person,i)=>{const check=m.attendance?.find(a=>a.personId===person.id)||m.attendance?.find(a=>a.name===person.name),checked=hasChecked(m,person);return `<div class="attendee-row" data-attendee="${esc(person.id)}">${avatar(person.name,i,'',person.id)}<span>${esc(personLabel(person))}</span><span class="attendee-state ${checked?'checked':''}">${checked?`已签到 · ${check?.method||'历史签到'}`:'待签到'}${check?.at?`<small>${check.at.slice(0,16).replace('T',' ')}</small>`:''}${check?.reason?`<small>补签：${esc(check.reason)} · ${esc(check.operator)}</small>`:''}</span></div>`}).join('')}</section><section class="detail-section"><h3>工作分配 ${canWrite&&m.status!=='已取消'&&(isLeader||isOrganizer||isHost)?'<button class="text-link" style="float:right" data-action="new-assignment">＋ 新增分工</button>':''}</h3>${state.assignments.filter(a=>a.meetingId===m.id||(!a.meetingId&&a.meeting===m.title)).map(a=>`<div class="attendee-row"><span>☷　${esc(a.content)}</span><span class="attendee-state">${esc(a.owner)}</span></div>`).join('')||'<p>会议产生的分工会显示在这里。</p>'}</section></div></div>`}
function render(){if(currentView==='profile'){const el=$('#page-content');el.innerHTML=profilePage();syncUserMenu();const crumb=$('.breadcrumbs strong');if(crumb)crumb.textContent='个人账户';return}if(!state){renderProjects();syncUserMenu();return}if(currentView==='projects'){renderProjects();syncUserMenu();return}renderSide();const el=$('#page-content');el.innerHTML=selectedMeeting?meetingDetail(selectedMeeting):({overview,meetings,work,journal,members,timeline,personal,settings,profile:profilePage,projects:()=>renderProjects()}[currentView]||overview)();if(currentView==='members')$('.heading-actions')?.insertAdjacentHTML('afterbegin','<button class="button" data-action="accept-invite">接受邀请码</button>');if(selectedMeeting){if(state.project.status!=='已归档'&&selectedMeeting.status==='待召开'&&(currentUser.role==='组长'||belongsToCurrent(selectedMeeting.organizerId,selectedMeeting.organizer)))$('.heading-actions')?.insertAdjacentHTML('beforeend','<button class="button" data-action="edit-meeting">编辑安排</button>');if(state.project.status!=='已归档'&&['进行中','已结束'].includes(selectedMeeting.status))document.querySelectorAll('[data-attendee]').forEach(row=>{const name=row.dataset.attendee;if(name&&!hasChecked(selectedMeeting,state.people.find(p=>p.id===name)||{id:name,name})&&currentUser.role==='组长')row.insertAdjacentHTML('beforeend',`<button class="button small" data-action="supplement" data-person="${esc(name)}">组长补签</button>`)});const box=[...document.querySelectorAll('.detail-section')].find(x=>x.textContent.includes('会议资料'));if(box){const fs=(state.files||[]).filter(f=>f.meetingId===selectedMeeting.id);if(fs.length)box.insertAdjacentHTML('beforeend',fs.map(f=>`<div class="attendee-row">▧　${esc(f.name)} <a class="text-link" href="/api/files/download?id=${encodeURIComponent(f.id)}&projectId=${encodeURIComponent(currentProjectId)}">下载</a><span class="attendee-state">${esc(f.uploadedBy)} · ${esc(f.uploadedAt.slice(0,10))}</span></div>`).join(''));else box.insertAdjacentHTML('beforeend','<p class="empty-copy">还没有会议资料，可在会议开始前上传。</p>')}const history=[...state.events.filter(ev=>ev.meetingId===selectedMeeting.id).map(ev=>({title:ev.title,detail:ev.detail,at:ev.at||ev.date})),...(selectedMeeting.changes||[]).map(change=>({title:'修改会议安排',detail:`${change.by} · ${change.before.date} ${change.before.start} → ${change.after.date} ${change.after.start}`,at:change.at}))].sort((a,b)=>String(b.at).localeCompare(String(a.at)));if(history.length){const panel=document.createElement('section');panel.className='detail-section';panel.innerHTML=`<h3>会议操作历史</h3>${history.map(ev=>`<div class="history-event"><b>${esc(ev.title)}</b><small>${esc(ev.detail)} · ${esc(String(ev.at).slice(0,16).replace('T',' '))}</small></div>`).join('')}`;document.querySelector('.meeting-detail-grid>div:last-child')?.append(panel)}if(state.project.status!=='已归档'&&selectedMeeting.status==='进行中'&&meetingMembers(selectedMeeting).some(p=>p.id===currentUser.id)&&!hasChecked(selectedMeeting,currentUser)){const own=document.querySelector(`[data-attendee="${CSS.escape(currentUser.id)}"]`);own?.insertAdjacentHTML('beforeend','<button class="button small" data-action="checkin">本人签到</button>')}}}
function toast(text){const el=document.createElement('div');el.className='toast';el.textContent=text;$('#toast-region').append(el);setTimeout(()=>el.remove(),2800)}
function modal(title,content,submitLabel='保存'){const layer=$('#modal-layer');layer.innerHTML=`<div class="modal" role="dialog" aria-modal="true"><div class="modal-head"><h2>${title}</h2><button class="modal-close" data-action="close-modal" aria-label="关闭">×</button></div><div class="modal-body">${content}</div><div class="form-foot"><button class="button" data-action="close-modal">取消</button><button class="button primary" data-action="submit-modal">${submitLabel}</button></div></div>`;layer.hidden=false;}
function openEditMeeting(m){modal('修改会议安排',`<form id="meeting-form" class="form-grid"><input type="hidden" name="id" value="${esc(m.id)}"><div class="field full"><label>会议名称 *</label><input name="title" maxlength="100" required value="${esc(m.title)}"></div><div class="field full"><label>会议议题 *</label><textarea name="topic" maxlength="3000" required>${esc(m.topic)}</textarea></div><div class="field"><label>日期 *</label><input name="date" type="date" required value="${esc(m.date)}"></div><div class="field"><label>会议形式</label><select name="format" id="meeting-format"><option ${m.format==='线下'?'selected':''}>线下</option><option ${m.format==='线上'?'selected':''}>线上</option></select></div><div class="field"><label>开始时间 *</label><input name="start" type="time" value="${esc(m.start)}" required></div><div class="field"><label>结束时间 *</label><input name="end" type="time" value="${esc(m.end)}" required></div><div class="field"><label>主持人 *</label><select name="host">${state.people.map(p=>`<option value="${esc(p.id)}" ${belongsToCurrent(m.hostId,m.host,p)?'selected':''}>${esc(personLabel(p))}</option>`).join('')}</select></div><div class="field"><label id="meeting-location-label">${m.format==='线上'?'会议链接 *':'会议地点 *'}</label><input name="location" ${m.format==='线上'?'type="url"':'type="text"'} required maxlength="200" value="${esc(m.location||'')}"></div><div class="field full"><label>应参会成员 *</label><div class="check-list">${state.people.map((p,i)=>`<label class="check-option">${avatar(p.name,i,'',p.id)}<input type="checkbox" name="attendees" value="${esc(p.id)}" ${m.attendeeIds?.includes(p.id)||(!Array.isArray(m.attendeeIds)&&m.attendees.includes(p.name)&&uniquePersonByName(p.name)?.id===p.id)?'checked':''}>${esc(p.name)}</label>`).join('')}</div></div></form>`,'保存安排')}
function openCreateProject(){modal('创建项目',`<form id="project-form"><div class="field"><label>项目名称 *</label><input name="name" maxlength="50" required placeholder="为项目起一个清晰的名字"></div><div class="field"><label>项目主题与说明 *</label><textarea name="topic" maxlength="2000" required placeholder="项目要解决的问题、目标和主要内容"></textarea></div><div class="form-grid"><div class="field"><label>开始日期 *</label><input name="startDate" type="date" required value="${localDate()}"></div><div class="field"><label>计划结束日期</label><input name="endDate" type="date"></div></div></form>`,'创建项目')}
function openNewMeeting(){modal('发起会议',`<form id="meeting-form" class="form-grid"><div class="field full"><label>会议名称 *</label><input name="title" maxlength="100" required placeholder="例如：第三轮访谈复盘"></div><div class="field full"><label>会议议题 *</label><textarea name="topic" maxlength="3000" required placeholder="希望讨论或达成什么"></textarea></div><div class="field"><label>日期 *</label><input name="date" type="date" required value="${new Date(Date.now()+86400000).toISOString().slice(0,10)}"></div><div class="field"><label>会议形式 *</label><select name="format" id="meeting-format"><option>线下</option><option>线上</option></select></div><div class="field"><label>开始时间 *</label><input name="start" type="time" value="14:00" required></div><div class="field"><label>结束时间 *</label><input name="end" type="time" value="15:00" required></div><div class="field"><label>主持人 *</label><select name="host">${state.people.map(p=>`<option value="${esc(p.id)}" ${p.id===currentUser.id?'selected':''}>${esc(personLabel(p))}</option>`).join('')}</select></div><div class="field"><label id="meeting-location-label">会议地点 *</label><input name="location" required maxlength="200" placeholder="填写线下会议地点"></div><div class="field full"><label>应参会成员 *</label><div class="check-list">${state.people.map((p,i)=>`<label class="check-option">${avatar(p.name,i,'',p.id)}<input type="checkbox" name="attendees" value="${esc(p.id)}" checked>${esc(p.name)}</label>`).join('')}</div></div></form>`,'创建会议')}
function openNewLog(existing=null){modal(existing?'编辑工作日志':'记录工作日志',`<form id="log-form"><input type="hidden" name="id" value="${esc(existing?.id||'')}"><input type="hidden" name="version" value="${existing?.version||1}"><div class="form-grid"><div class="field"><label>工作日期 *</label><input name="date" type="date" value="${esc(existing?.date||localDate())}" required></div><div class="field"><label>关联分工（选填）</label><select name="linkAssignmentId"><option value="">不关联</option>${state.assignments.filter(a=>belongsToCurrent(a.ownerId,a.owner)||existing?.linkAssignmentId===a.id||existing?.link===a.content).map(a=>`<option value="${esc(a.id)}" ${existing?.linkAssignmentId===a.id||(!existing?.linkAssignmentId&&existing?.link===a.content)?'selected':''}>${esc(a.content)}</option>`).join('')}</select></div><div class="field full"><label>工作内容 *</label>${richEditor('log',existing?.textHtml,existing?.text,existing?.id||'')}</div><div class="field full"><label>附件（每条日志最多50个；单个不超过20MB）</label><input name="attachments" type="file" multiple accept=".pdf,.doc,.docx,.xls,.xlsx,.ppt,.pptx,.txt,.md,.png,.jpg,.jpeg,.zip"><small class="subtle">支持 PDF、Office、文本、图片和 ZIP。附件上传权限仅限日志作者。</small></div></div></form>`,existing?'保存修改':'发布日志')}
function openNewLog(existing=null){modal(existing?'编辑工作日志':'记录工作日志',`<form id="log-form"><input type="hidden" name="id" value="${esc(existing?.id||'')}"><input type="hidden" name="version" value="${existing?.version||1}"><div class="form-grid"><div class="field"><label>工作日期 *</label><input name="date" type="date" max="${localDate()}" value="${esc(existing?.date||localDate())}" required></div><div class="field"><label>关联会议（选填）</label><select name="meetingId"><option value="">不关联</option>${state.meetings.map(m=>`<option value="${esc(m.id)}" ${existing?.meetingId===m.id?'selected':''}>${esc(m.title)} · ${esc(m.date)}</option>`).join('')}</select></div><div class="field"><label>关联分工（选填）</label><select name="linkAssignmentId"><option value="">不关联</option>${state.assignments.filter(a=>belongsToCurrent(a.ownerId,a.owner)||existing?.linkAssignmentId===a.id||existing?.link===a.content).map(a=>`<option value="${esc(a.id)}" ${existing?.linkAssignmentId===a.id||(!existing?.linkAssignmentId&&existing?.link===a.content)?'selected':''}>${esc(a.content)}</option>`).join('')}</select></div><div class="field full"><label>工作内容 *</label>${richEditor('log',existing?.textHtml,existing?.text,existing?.id||'')}</div><div class="field full"><label>附件（每条日志最多50个；单个不超过20MB）</label><input name="attachments" type="file" multiple accept=".pdf,.doc,.docx,.xls,.xlsx,.ppt,.pptx,.txt,.md,.png,.jpg,.jpeg,.zip"><small class="subtle">支持 PDF、Office、文本、图片和 ZIP。附件上传权限仅限日志作者。</small></div></div></form>`,existing?'保存修改':'发布日志')}
function openAssignment(existing=null){modal(existing?'调整工作分配':'新增工作分配',`<form id="assignment-form"><input type="hidden" name="id" value="${esc(existing?.id||'')}"><input type="hidden" name="version" value="${existing?.version||1}"><div class="field"><label>工作内容 *</label><textarea name="content" maxlength="2000" required placeholder="描述具体事项">${esc(existing?.content||'')}</textarea></div><div class="field"><label>补充说明（选填）</label><textarea name="note" maxlength="1000" placeholder="背景、交付位置或需要留意的事项">${esc(existing?.note||'')}</textarea></div><div class="form-grid"><div class="field full"><label>关联会议 *</label><select name="meetingId" required>${state.meetings.filter(m=>m.status!=='已取消').map(m=>`<option value="${esc(m.id)}" ${existing?.meetingId===m.id||(!existing&&m.id===(selectedMeeting?.id||state.meetings.find(x=>x.status!=='已取消')?.id))?'selected':''}>${esc(m.title)} · ${esc(m.date)} (${esc(m.status)})</option>`).join('')}</select></div><div class="field"><label>负责人 *</label><select name="owner" required>${existing&&!existing.ownerId&&!uniquePersonByName(existing.owner)?`<option value="" selected disabled>历史负责人身份不明确，请选择成员</option>`:""}${state.people.map(p=>`<option value="${esc(p.id)}" ${belongsToCurrent(existing?.ownerId,existing?.owner,p)?'selected':''}>${esc(personLabel(p))}</option>`).join('')}</select></div><div class="field"><label>计划完成日期</label><input name="due" type="date" value="${esc(existing?.due||'')}"></div></div></form>`,existing?'保存调整':'保存分配')}
async function request(path,method='GET',data){const r=await fetch(path,{method,credentials:'same-origin',headers:{'content-type':'application/json',...(currentProjectId?{'X-Project-Id':currentProjectId}:{})},...(data?{body:JSON.stringify(data)}:{})});const v=await r.json();if(!r.ok)throw Error(v.error||'操作失败');return v}
async function submitModal(){const form=$('.modal form');if(!form){closeModal();render();return}if(!form.reportValidity())return;const fd=new FormData(form);const submit=$('[data-action=submit-modal]');if(submit){submit.disabled=true;submit.textContent='正在保存…'}const editorState=form.querySelector('[data-editor-state]');if(editorState)editorState.textContent='正在保存到服务器…';try{if(form.id==='project-form'){const p=await request('/api/projects','POST',Object.fromEntries(fd.entries()));currentProjectId=p.id;localStorage.setItem('projectId',p.id);currentView='overview';closeModal();await load();toast('项目已创建，你现在是组长');return}else if(form.id==='meeting-form'){const data=Object.fromEntries(fd.entries());data.attendeeIds=fd.getAll('attendees');delete data.attendees;data.hostId=data.host;delete data.host;let m;if(data.id){m=await request('/api/meetings','PATCH',data);selectedMeeting=m;state.meetings[state.meetings.findIndex(x=>x.id===m.id)]=m;toast('会议安排已更新')}else{m=await request('/api/meetings','POST',data);state.meetings.unshift(m);selectedMeeting=m;currentView='meetings';toast('会议已创建')}}else if(form.id==='log-form'){const data=Object.fromEntries(fd.entries());delete data.attachments;let l;if(data.id){l=await request('/api/logs','PATCH',data);const i=state.logs.findIndex(x=>x.id===l.id);if(i>=0)state.logs[i]=l;toast('工作日志已更新')}else{l=await request('/api/logs','POST',data);state.logs.unshift(l);form.elements.id.value=l.id;form.elements.version.value=l.version||1;toast('工作日志已发布')}form.elements.version.value=l.version||1;const input=form.elements.attachments;if(input?.files?.length){form.dataset.uploaded||='';const done=new Set(form.dataset.uploaded.split('|').filter(Boolean));for(const file of input.files){const key=`${file.name}:${file.size}:${file.lastModified}`;if(done.has(key))continue;const upload=new FormData();upload.append('file',file);upload.append('logId',l.id);const response=await fetch('/api/files',{method:'POST',credentials:'same-origin',headers:{'X-Project-Id':currentProjectId},body:upload});const result=await response.json();if(!response.ok)throw Error(result.error||`附件“${file.name}”上传失败`);state.files.unshift(result);done.add(key);form.dataset.uploaded=[...done].join('|')} }currentView='journal';}else if(form.id==='supplement-form'){const m=await request('/api/meetings/supplement','POST',{meetingId:selectedMeeting.id,personId:fd.get('personId'),reason:fd.get('reason')});Object.assign(selectedMeeting,m);state.meetings[state.meetings.findIndex(x=>x.id===m.id)]=m;toast('补签已保存')}else if(form.id==='invite-preview-form'){const code=String(fd.get('code')||'').trim().toUpperCase();const preview=await request(`/api/invites/preview?code=${encodeURIComponent(code)}`);modal('确认加入项目',`<div class="invite-preview"><div class="eyebrow">PROJECT INVITATION</div><h3>${esc(preview.project.name)}</h3><p>${esc(preview.project.topic)}</p><span>项目组长：${esc(preview.project.leader)}</span><form id="invite-accept-form"><input type="hidden" name="code" value="${esc(code)}"></form></div>`,'确认加入')}else if(form.id==='invite-accept-form'){const result=await request('/api/invites/accept','POST',Object.fromEntries(fd.entries()));if(result.projectId){currentProjectId=result.projectId;localStorage.setItem('projectId',currentProjectId)}currentView='overview';await load();toast(result.message||'已加入项目')}else if(form.id==='assignment-form'){const data=Object.fromEntries(fd.entries());data.ownerId=data.owner;delete data.owner;data.meetingId||=selectedMeeting?.id||state.meetings.find(m=>m.status!=='已取消')?.id||'';let a;if(data.id){a=await request('/api/assignments','PATCH',data);const ix=state.assignments.findIndex(x=>x.id===a.id);if(ix>=0)state.assignments[ix]=a}else{a=await request('/api/assignments','POST',data);state.assignments.unshift(a)}toast('工作分配已保存');}else if(form.id==='minutes-form'){const m=await request('/api/meetings/summary','PATCH',{id:selectedMeeting.id,summary:fd.get('summary'),summaryHtml:fd.get('summaryHtml'),version:fd.get('version')});Object.assign(selectedMeeting,m);const idx=state.meetings.findIndex(x=>x.id===m.id);state.meetings[idx]=m;toast('会议纪要已保存');}if(editorState)editorState.textContent='服务端已保存';closeModal();render()}catch(e){if(editorState)editorState.textContent='保存失败，输入仍保留';toast(e.message)}finally{if(submit){submit.disabled=false;submit.textContent='重试保存'}}}
function closeModal(){$('#modal-layer').hidden=true;$('#modal-layer').innerHTML=''}
async function statusMeeting(status){let reason='';if(status==='已取消'){reason=prompt('请填写取消原因，以便参会成员了解变更。');if(reason===null)return;if(!reason.trim()){toast('取消会议需要填写原因');return}}try{const m=await request('/api/meetings/status','PATCH',{id:selectedMeeting.id,status,reason});Object.assign(selectedMeeting,m);const idx=state.meetings.findIndex(x=>x.id===m.id);state.meetings[idx]=m;toast(`会议已${status}`);render()}catch(e){toast(e.message)}}
document.addEventListener('click',async e=>{const nav=e.target.closest('[data-view]');if(nav){currentView=nav.dataset.view;selectedMeeting=null;if(currentView==='personal')currentPerson=currentUser?.id||'';render();$('#sidebar').classList.remove('open');return}const open=e.target.closest('[data-open-meeting]');if(open){selectedMeeting=state.meetings.find(m=>m.id===open.dataset.openMeeting);currentView='meetings';render();return}const el=e.target.closest('[data-action]');if(!el)return;switch(el.dataset.action){case'toggle-mine':showMine=!showMine;workMemberFilter='全部成员';render();break;case'filter-assignment-owner':workMemberFilter=el.dataset.owner||'全部成员';showMine=false;render();break;case'view-assignment':{const a=state.assignments.find(x=>x.id===el.dataset.id);if(a){const history=(a.changeHistory||[]).map(h=>`<div class="history-event"><b>${esc(h.by)} 调整了分工</b><small>${esc(String(h.at||'').slice(0,16).replace('T',' '))} · ${esc(h.before?.owner||'')} → ${esc(h.after?.owner||a.owner)}</small></div>`).join('');modal('分工详情',`<div class="assignment-detail"><div class="eyebrow">分工记录</div><h3>${esc(a.content)}</h3><p>${esc(a.note||'暂无补充说明。')}</p><dl><div><dt>负责人</dt><dd>${esc(a.owner)}</dd></div><div><dt>关联会议</dt><dd>${esc(a.meeting||'未记录')}</dd></div><div><dt>分配人</dt><dd>${esc(a.by||'历史记录')}</dd></div><div><dt>计划日期</dt><dd>${esc(a.due||'未设置')}</dd></div></dl>${history?`<section class="assignment-history"><h4>变更留痕</h4>${history}</section>`:'<p class="subtle">暂无负责人变更记录。</p>'}</div>`,'完成')}break;}case'timeline-more':eventLimit+=20;render();break;case'toggle-project-menu':{const menu=$('#project-menu'),button=$('#workspace-toggle');if(menu){menu.hidden=!menu.hidden;button?.setAttribute('aria-expanded',String(!menu.hidden))}break;}case'retry-load':load();break;case'create-project':openCreateProject();break;case'open-project':currentProjectId=el.dataset.project;localStorage.setItem('projectId',currentProjectId);selectedMeeting=null;currentView='overview';currentPerson=currentUser?.id||'';showMine=false;workMemberFilter='全部成员';logAuthorFilter='全部成员';eventTypeFilter='全部动态';eventPersonFilter='全部成员';eventFrom='';eventTo='';$('#project-menu').hidden=true;$('#workspace-toggle')?.setAttribute('aria-expanded','false');await load();break;case'global-search':currentView='meetings';render();$('#meeting-search')?.focus();break;case'new-meeting':openNewMeeting();break;case'new-log':openNewLog();break;case'new-assignment':openAssignment();break;case'edit-assignment':{const a=state.assignments.find(x=>x.id===el.dataset.id);if(a)openAssignment(a);break;}case'close-modal':closeModal();break;case'submit-modal':submitModal();break;case'back-meetings':selectedMeeting=null;currentView='meetings';render();break;case'start-meeting':statusMeeting('进行中');break;case'end-meeting':statusMeeting('已结束');break;case'cancel-meeting':statusMeeting('已取消');break;case'edit-minutes':modal('编辑会议纪要',`<form id="minutes-form"><div class="field"><label>讨论摘要与结论</label><input type="hidden" name="version" value="${selectedMeeting.summaryVersion||1}">${richEditor('minutes',selectedMeeting.summaryHtml,selectedMeeting.summary,selectedMeeting.id)}</div></form>`,'保存纪要');break;case'invite-member':case'invite-mini':try{const i=await request('/api/invites','POST',{});state.invites.unshift(i);modal('邀请项目成员',`<div class="status-banner">请将邀请码分享给项目成员。邀请码有效期至 ${esc(i.expiresAt.slice(0,10))}。登录成员可在“我的项目”预览项目后确认加入。</div><div class="field"><label>项目邀请码</label><div class="copy-row"><input id="invite-code" readonly value="${esc(i.code)}"><button class="button" data-action="copy-invite">复制</button></div></div>`,'完成');toast('邀请已生成');}catch(err){toast(err.message)}break;case'accept-invite':modal('接受项目邀请',`<form id="invite-preview-form"><div class="field"><label>邀请码 *</label><input name="code" required maxlength="10" placeholder="输入邀请码"></div></form>`,'加入项目');break;case'revoke-invite':try{await request('/api/invites/revoke','POST',{id:el.dataset.id});state=await request('/api/state');toast('邀请码已失效');render()}catch(err){toast(err.message)}break;case'copy-invite':navigator.clipboard?.writeText($('#invite-code')?.value||'').then(()=>toast('邀请码已复制')).catch(()=>toast('请手动复制邀请码'));break;case'member-timeline':currentPerson=el.dataset.person;currentView='personal';render();break;case'save-project':try{const fields=document.querySelectorAll('.settings-grid .settings-card:first-child input,.settings-grid .settings-card:first-child textarea');const p=await request('/api/project','PATCH',{name:fields[0].value,topic:fields[1].value,startDate:fields[2].value,endDate:fields[3].value});state.project=p;toast('项目信息已保存');render()}catch(err){toast(err.message)}break;case'archive-project':if(!confirm('归档后，项目业务内容将进入只读状态。确认归档？'))break;try{state.project=await request('/api/project/archive','POST',{});toast('项目已归档');render()}catch(err){toast(err.message)}break;}});
document.addEventListener('change',e=>{if(e.target.id==='project-filter'){projectStatus=e.target.value;renderProjects()}if(e.target.id==='meeting-filter'){meetingFilter=e.target.value;render()}if(e.target.id==='event-filter')document.querySelectorAll('[data-event-kind]').forEach(x=>x.hidden=e.target.value!=='全部动态'&&x.dataset.eventKind!==e.target.value);if(e.target.id==='log-author-filter'){logAuthorFilter=e.target.value;render()}if(e.target.id==='personal-person-filter'){currentPerson=e.target.value;render()}if(e.target.id==='event-filter'){eventTypeFilter=e.target.value;eventLimit=20;render()}if(e.target.id==='event-person-filter'){eventPersonFilter=e.target.value;eventLimit=20;render()}if(e.target.id==='event-from'){eventFrom=e.target.value;eventLimit=20;render()}if(e.target.id==='event-to'){eventTo=e.target.value;eventLimit=20;render()}});
document.addEventListener('input',e=>{if(e.target.id==='project-search'){projectQuery=e.target.value;const pos=e.target.selectionStart;renderProjects();const input=$('#project-search');input.focus();input.setSelectionRange(pos,pos)}if(e.target.id==='meeting-search'){query=e.target.value;const pos=e.target.selectionStart;render();const input=$('#meeting-search');input.focus();input.setSelectionRange(pos,pos)}if(e.target.id==='log-search'){logQuery=e.target.value;const pos=e.target.selectionStart;render();const input=$('#log-search');input?.focus();input?.setSelectionRange(pos,pos)}});
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;if(b.dataset.action==='edit-log'){const log=state.logs.find(x=>x.id===b.dataset.id);if(log)openNewLog(log)}if(b.dataset.action==='accept-invite')modal('接受项目邀请',`<form id="invite-preview-form"><div class="field"><label>邀请码 *</label><input name="code" required maxlength="10" placeholder="输入 10 位邀请码"></div></form>`,'加入项目');if(b.dataset.action==='upload-file'){const input=document.createElement('input');input.type='file';input.accept='.pdf,.doc,.docx,.xls,.xlsx,.ppt,.pptx,.txt,.md,.png,.jpg,.jpeg,.zip';input.multiple=true;input.onchange=async()=>{if(!input.files.length)return;if(input.files.length>5){toast('单次最多选择5个文件');return}try{for(const file of input.files){const fd=new FormData();fd.append('meetingId',selectedMeeting.id);fd.append('file',file);const r=await fetch('/api/files',{method:'POST',credentials:'same-origin',headers:{'X-Project-Id':currentProjectId},body:fd});const x=await r.json();if(!r.ok)throw Error(`${file.name}：${x.error}`)}state=await request('/api/state');selectedMeeting=state.meetings.find(m=>m.id===selectedMeeting.id);toast('资料上传成功');render()}catch(err){toast(err.message)}};input.click()}if(b.dataset.action==='checkin'){try{const m=await request('/api/meetings/checkin','POST',{meetingId:selectedMeeting.id});Object.assign(selectedMeeting,m);state.meetings[state.meetings.findIndex(x=>x.id===m.id)]=m;toast('签到成功');render()}catch(err){toast(err.message)}}});
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;if(b.dataset.action==='edit-meeting'&&selectedMeeting)openEditMeeting(selectedMeeting);if(b.dataset.action==='supplement'&&selectedMeeting){const person=state.people.find(p=>p.id===b.dataset.person);modal('补录签到',`<form id="supplement-form"><input type="hidden" name="personId" value="${esc(person?.id)}"><div class="field"><label>参会成员</label><input readonly value="${esc(person?personLabel(person):'未知成员')}"></div><div class="field"><label>补签原因 *</label><textarea name="reason" required maxlength="500" placeholder="说明补签原因"></textarea></div></form>`,'确认补签')}});
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action=logout]');if(!b)return;await fetch('/api/logout',{method:'POST',credentials:'same-origin'});location.reload()});
document.addEventListener('click',e=>{const b=e.target.closest('[data-auth-mode]');if(b)renderAuth(b.dataset.authMode)});
document.addEventListener('submit',e=>{if(e.target.id!=='auth-form'||e.target.elements.mode.value!=='register')return;const password=e.target.elements.password.value,confirmation=e.target.elements.confirmPassword.value;if(password!==confirmation){e.preventDefault();e.stopImmediatePropagation();const box=e.target.querySelector('.auth-error');box?.remove();e.target.insertAdjacentHTML('beforeend','<div class="auth-error">两次输入的密码不一致，请重新确认。</div>')}},true);
document.addEventListener('change',e=>{if(e.target.id!=='meeting-format')return;const input=$('.modal input[name="location"]'),label=$('#meeting-location-label');if(!input||!label)return;const online=e.target.value==='线上';label.textContent=online?'会议链接 *':'会议地点 *';input.type=online?'url':'text';input.placeholder=online?'https://…':'填写线下会议地点';input.value='';input.setCustomValidity('')});
document.addEventListener('submit',async e=>{if(e.target.id!=='auth-form')return;e.preventDefault();const fd=new FormData(e.target),mode=fd.get('mode'),data=Object.fromEntries(fd.entries());delete data.mode;const submit=e.target.querySelector('[type=submit]');submit.disabled=true;submit.textContent='正在处理…';try{const r=await fetch(mode==='login'?'/api/login':'/api/register',{method:'POST',headers:{'content-type':'application/json'},credentials:'same-origin',body:JSON.stringify(data)});const result=await r.json();if(!r.ok)throw Error(result.error||'操作失败');if(mode==='register'){renderAuth('login');const box=$('#auth-layer');box.querySelector('form').insertAdjacentHTML('beforeend','<div class="auth-success">账号已创建，请使用新账号登录。</div>');}else location.reload()}catch(err){const box=$('#auth-layer');box.querySelector('.auth-error')?.remove();box.querySelector('form').insertAdjacentHTML('beforeend',`<div class="auth-error">${esc(err.message)}</div>`);submit.disabled=false;submit.textContent=mode==='login'?'登录项目空间':'创建账号'}});

document.addEventListener('click',e=>{const assignment=e.target.closest('[data-open-assignment]');if(assignment){currentView='work';selectedMeeting=null;showMine=false;workMemberFilter='全部成员';render();const target=document.querySelector(`[data-assignment="${CSS.escape(assignment.dataset.openAssignment)}"]`);target?.scrollIntoView({behavior:'smooth',block:'center'});target?.classList.add('focus-highlight');setTimeout(()=>target?.classList.remove('focus-highlight'),1500);return}const log=e.target.closest('[data-open-log]');if(log){currentView='journal';selectedMeeting=null;logAuthorFilter='全部成员';logQuery='';render();const target=document.querySelector(`[data-log="${CSS.escape(log.dataset.openLog)}"]`);target?.scrollIntoView({behavior:'smooth',block:'center'});target?.classList.add('focus-highlight');setTimeout(()=>target?.classList.remove('focus-highlight'),1500)}});
document.addEventListener('input',e=>{const editor=e.target.closest('[data-rich-editor]');if(!editor)return;const wrap=editor.closest('.rich-editor-wrap'),kind=editor.dataset.richEditor,html=editor.innerHTML,text=editor.innerText.trim();wrap.querySelector(`[name="${kind==='minutes'?'summary':'text'}"]`).value=text;wrap.querySelector(`[name="${kind==='minutes'?'summaryHtml':'textHtml'}"]`).value=html;const status=wrap.querySelector('[data-editor-state]');if(status)status.textContent='有未保存修改';});
document.addEventListener('click',async e=>{const button=e.target.closest('[data-action]');if(!button)return;if(button.dataset.action==='download-backup'){button.disabled=true;button.textContent='正在生成备份…';try{const r=await fetch('/api/backup',{credentials:'same-origin',headers:{'X-Project-Id':currentProjectId}});if(!r.ok){const err=await r.json();throw Error(err.error||'备份失败')}const blob=await r.blob(),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`${state.project.name}-项目备份.zip`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('项目备份已下载')}catch(err){toast(err.message)}finally{button.disabled=false;button.textContent='下载项目备份 ZIP'}}if(button.dataset.action==='choose-restore')$('#backup-file')?.click()});
document.addEventListener('change',async e=>{if(e.target.id!=='backup-file'||!e.target.files?.length)return;const file=e.target.files[0];if(file.size>110*1024*1024){toast('备份文件不能超过110MB');e.target.value='';return}if(!confirm(`将使用“${file.name}”覆盖当前项目“${state.project.name}”的数据。请确认已备份当前内容。`)){e.target.value='';return}try{const bytes=new Uint8Array(await file.arrayBuffer());let binary='';for(let offset=0;offset<bytes.length;offset+=0x8000)binary+=String.fromCharCode(...bytes.subarray(offset,offset+0x8000));const archive=btoa(binary);toast('正在验证备份并恢复项目…');const restored=await request('/api/backup/restore','POST',{archive});await load();toast(`项目已恢复，包含 ${restored.files} 个附件`)}catch(err){toast(err.message)}finally{e.target.value=''}});
document.addEventListener('mousedown',e=>{const tool=e.target.closest('[data-editor-command]');if(tool){const sel=getSelection();if(sel?.rangeCount)tool.closest('.rich-editor-wrap').dataset.savedRange='1';e.preventDefault()}});document.addEventListener('click',async e=>{const listItem=e.target.closest('[data-rich-editor] li[data-checked]');if(listItem&&e.offsetX<28){const checked=listItem.dataset.checked!=='true';listItem.dataset.checked=String(checked);listItem.textContent=`${checked?'☑':'☐'} ${listItem.textContent.replace(/^[☐☑]\s*/, '')}`;listItem.closest('[data-rich-editor]').dispatchEvent(new InputEvent('input',{bubbles:true}));return}const tool=e.target.closest('[data-editor-command]');if(!tool)return;const editor=tool.closest('.rich-editor-wrap')?.querySelector('[data-rich-editor]');if(!editor)return;const cmd=tool.dataset.editorCommand;editor.focus();if(cmd==='image'){const input=document.createElement('input');input.type='file';input.accept='image/png,image/jpeg';input.onchange=async()=>{const file=input.files?.[0];if(!file)return;if(file.size>10*1024*1024){toast('正文图片不能超过10MB');return}try{const fd=new FormData();fd.append('file',file);fd.append('kind',editor.dataset.richEditor);fd.append('recordId',editor.closest('.rich-editor-wrap').dataset.recordId||'');const r=await fetch('/api/editor-images',{method:'POST',credentials:'same-origin',headers:{'X-Project-Id':currentProjectId},body:fd});const result=await r.json();if(!r.ok)throw Error(result.error||'图片上传失败');document.execCommand('insertHTML',false,`<img src="${esc(result.url)}" alt="${esc(file.name)}">`);editor.dispatchEvent(new InputEvent('input',{bubbles:true}));}catch(err){toast(err.message)}};input.click();return}if(cmd==='link'){const href=prompt('输入 https:// 开头的链接');if(href&&/^https?:\/\//i.test(href))document.execCommand('createLink',false,href);else if(href)toast('链接必须以 http:// 或 https:// 开头')}else if(/^h[1-3]$/.test(cmd))document.execCommand('formatBlock',false,cmd);else if(cmd==='blockquote')document.execCommand('formatBlock',false,'blockquote');else if(cmd==='color'||cmd==='highlight'){if(!getSelection()?.toString()){toast('请先选中需要设置样式的文字');return}const color=prompt(cmd==='color'?'输入十六进制文字颜色，例如 #3158d9':'输入十六进制高亮颜色，例如 #fff0b3',cmd==='color'?'#3158d9':'#fff0b3');if(color&&/^#[0-9a-f]{3,8}$/i.test(color))document.execCommand('insertHTML',false,`<span style="${cmd==='color'?'color':'background-color'}:${color}">${getSelection()?.toString()||'选中文字'}</span>`);else if(color)toast('请输入有效的十六进制颜色')}else if(cmd==='checklist')document.execCommand('insertHTML',false,'<ul data-checklist="true"><li data-checked="false">☐ 清单事项</li></ul>');else if(cmd==='hr')document.execCommand('insertHTML',false,'<hr><p><br></p>');else if(cmd==='table')document.execCommand('insertHTML',false,'<table><tbody><tr><th>标题一</th><th>标题二</th></tr><tr><td>内容</td><td>内容</td></tr></tbody></table><p><br></p>');else if(['add-row','add-column','delete-row','delete-column'].includes(cmd)){const sel=getSelection(),cell=sel?.anchorNode?.parentElement?.closest('td,th'),table=cell?.closest('table');if(!cell||!table){toast('请先将光标放在需要调整的表格内');return}const row=cell.parentElement,index=cell.cellIndex;if(cmd==='add-row'){if(table.rows.length>=20){toast('每张表格最多20行');return}const tr=table.insertRow(row.rowIndex+1);for(let i=0;i<row.cells.length;i++){const c=tr.insertCell();c.innerHTML='内容'}}else if(cmd==='add-column'){if(row.cells.length>=10){toast('每张表格最多10列');return}for(const r of table.rows){const c=r.insertCell(index+1);c.innerHTML='内容'}}else if(cmd==='delete-row'){if(table.rows.length<=1){toast('表格至少保留一行');return}table.deleteRow(row.rowIndex)}else{if(row.cells.length<=1){toast('表格至少保留一列');return}for(const r of table.rows)r.deleteCell(index)}}else if(cmd==='checklist-toggle'){const li=getSelection()?.anchorNode?.parentElement?.closest('li');if(li){const checked=li.dataset.checked!=='true';li.dataset.checked=String(checked);li.textContent=`${checked?'☑':'☐'} ${li.textContent.replace(/^[☐☑]\s*/, '')}`}}else document.execCommand(cmd,false,null);editor.dispatchEvent(new InputEvent('input',{bubbles:true}));});
document.addEventListener('paste',async e=>{const editor=e.target.closest('[data-rich-editor]');if(!editor)return;const image=[...(e.clipboardData?.items||[])].find(x=>x.type.startsWith('image/'));if(!image){const source=e.clipboardData?.getData('text/html');if(source){e.preventDefault();const doc=new DOMParser().parseFromString(source,'text/html'),allowed=new Set(['P','BR','H1','H2','H3','STRONG','B','EM','I','U','S','UL','OL','LI','BLOCKQUOTE','A','TABLE','THEAD','TBODY','TR','TD','TH','HR','SPAN']);doc.querySelectorAll('script,style,iframe,object,embed,svg,math,form,img').forEach(n=>n.remove());const clean=node=>{for(const child of [...node.children]){if(!allowed.has(child.tagName)){child.replaceWith(...child.childNodes);continue}const href=child.getAttribute('href')||'',style=child.getAttribute('style')||'',checked=child.getAttribute('data-checked'),checklist=child.getAttribute('data-checklist');for(const a of [...child.attributes])child.removeAttribute(a.name);if(child.tagName==='A'&&/^https?:\/\//i.test(href))child.setAttribute('href',href);if(child.tagName==='SPAN'){const color=style.match(/(?:^|;)\s*color\s*:\s*(#[0-9a-f]{3,8})/i)?.[1],bg=style.match(/(?:^|;)\s*background-color\s*:\s*(#[0-9a-f]{3,8})/i)?.[1];const safe=[color&&`color:${color}`,bg&&`background-color:${bg}`].filter(Boolean).join(';');if(safe)child.setAttribute('style',safe)}if(child.tagName==='LI'&&['true','false'].includes(checked))child.setAttribute('data-checked',checked);if(child.tagName==='UL'&&checklist==='true')child.setAttribute('data-checklist','true');clean(child)}};clean(doc.body);document.execCommand('insertHTML',false,doc.body.innerHTML);editor.dispatchEvent(new InputEvent('input',{bubbles:true}));return}return;}e.preventDefault();const file=image.getAsFile();if(!file)return;try{const fd=new FormData();const ext=({'image/png':'png','image/jpeg':'jpg'})[file.type];if(!ext){toast('粘贴图片仅支持 PNG、JPG、JPEG');return}if(file.size>10*1024*1024){toast('正文图片不能超过10MB');return}fd.append('file',file,`pasted-image.${ext}`);fd.append('kind',editor.dataset.richEditor);fd.append('recordId',editor.closest('.rich-editor-wrap').dataset.recordId||'');const r=await fetch('/api/editor-images',{method:'POST',credentials:'same-origin',headers:{'X-Project-Id':currentProjectId},body:fd});const result=await r.json();if(!r.ok)throw Error(result.error||'图片粘贴失败');editor.focus();document.execCommand('insertHTML',false,`<img src="${esc(result.url)}" alt="粘贴图片">`);editor.dispatchEvent(new InputEvent('input',{bubbles:true}));}catch(err){toast(err.message)}});
$('#sidebar').addEventListener('click',e=>{const nav=e.target.closest('.nav-item[data-view]');if(!nav)return;e.preventDefault();e.stopPropagation();currentView=nav.dataset.view;if(currentView==='personal')currentPerson=currentUser?.id||'';selectedMeeting=null;render();$('#sidebar').classList.remove('open')},true);
document.addEventListener('click',e=>{if(!e.target.closest('#workspace-switch')){$('#project-menu').hidden=true;$('#workspace-toggle')?.setAttribute('aria-expanded','false')}});
$('#mobile-menu').addEventListener('click',()=>$('#sidebar').classList.toggle('open'));$('#modal-layer').addEventListener('click',e=>{if(e.target.id==='modal-layer')closeModal()});load();






